const oceanExplanation='<h3>Зачем нужна эта клетка?</h3><p>Эта клетка помогает проверить, не изменилась ли твоя точка зрения. Иногда мы начинаем путь с одним запросом, но новые осознания помогают увидеть, что за ним скрывается что-то другое.</p><h3>Твоя задача</h3><p>Посмотри на свой запрос еще раз. Оставь его, если он по-прежнему точен, или измени, если сейчас ты видишь ситуацию иначе.</p>';
function updateCurrentRequest(value,source='Океан иллюзий',eventId=null){const next=String(value).trim();if(!hasReflectionText(next))return false;const from=currentRequest();if(next!==from){game.requestHistory||=[];if(!eventId||!game.requestHistory.some(h=>h.eventId===eventId))game.requestHistory.push({eventId:eventId||globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`,source,level:game.level,cell:game.position,from,to:next,at:new Date().toISOString()});game.request=next}persist();return true}
function showOcean(){if(!game.pendingOcean){game.seenCells||={};const first=!game.seenCells.ocean;game.seenCells.ocean=true;game.pendingOcean={id:globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`,level:game.level,cell:game.position,first,state:'pending',mode:'choice',before:currentRequest(),draft:currentRequest(),at:new Date().toISOString()};persist()}const event=game.pendingOcean;if(event.mode==='edit'){showOceanEditor();return}playSound('oceanOfIllusions');ge('board').classList.remove('ocean-ripple');void ge('board').offsetWidth;ge('board').classList.add('ocean-ripple');setTimeout(()=>ge('board').classList.remove('ocean-ripple'),1500);showModal('Перепроверка запроса',event.first?'🌊 ОКЕАН ИЛЛЮЗИЙ':'🌊 Пересмотри свой запрос',`${event.first?oceanExplanation:''}<div class="ocean-questions"><p>Это все еще мой настоящий запрос?<br>Я действительно хочу именно этого?<br>Или сейчас я вижу свою ситуацию по-другому?</p></div><h3>МОЙ ПЕРВОНАЧАЛЬНЫЙ ЗАПРОС</h3><blockquote>${escapeHtml(game.originalRequest)}</blockquote>${currentRequest()!==game.originalRequest?`<h3>С ЧЕМ Я ИДУ СЕЙЧАС</h3><blockquote>${escapeHtml(currentRequest())}</blockquote>`:''}<h3>ХОЧЕШЬ ОСТАВИТЬ ЕГО ИЛИ ИЗМЕНИТЬ?</h3>${!event.first?`<details class="ocean-help"><summary>ⓘ Зачем нужен Океан иллюзий?</summary>${oceanExplanation}</details>`:''}`,[{label:event.first?'ОСТАВИТЬ ЗАПРОС':'ОСТАВИТЬ',action:()=>finishOcean('kept',event.id)},{label:event.first?'ПЕРЕСМОТРЕТЬ ЗАПРОС':'ИЗМЕНИТЬ',secondary:true,action:()=>{event.mode='edit';persist();showOceanEditor()}}]);ge('modal-close').hidden=true}
function showOceanEditor(){const event=game.pendingOcean;if(!event)return;showModal('Океан иллюзий','МОЙ ОБНОВЛЕННЫЙ ЗАПРОС',`<p>Что сейчас точнее отражает то, с чем ты хочешь идти дальше?</p><label for="ocean-request">Мой обновленный запрос</label><textarea id="ocean-request" maxlength="2000">${escapeHtml(event.draft)}</textarea><p class="modal-note">Первоначальный запрос и история изменений сохранятся в журнале.</p>`,[{label:'СОХРАНИТЬ НОВЫЙ ЗАПРОС',action:()=>{if(game.pendingOcean?.id!==event.id||!hasReflectionText(ge('ocean-request').value))return;ge('modal-buttons').querySelectorAll('button').forEach(b=>b.disabled=true);if(updateCurrentRequest(ge('ocean-request').value,'Океан иллюзий',event.id))finishOcean(currentRequest()===event.before?'kept':'changed',event.id)}},{label:'Назад к выбору',secondary:true,action:()=>{event.mode='choice';persist();showOcean()}}]);ge('modal-close').hidden=true;const input=ge('ocean-request'),button=ge('modal-buttons').querySelector('button');const validate=()=>{event.draft=input.value;button.disabled=!hasReflectionText(input.value);persist()};input.addEventListener('input',validate);button.disabled=!hasReflectionText(input.value);input.focus()}
function finishOcean(choice,id){const event=game.pendingOcean;if(!event||event.id!==id||event.state!=='pending')return;event.state=choice;game.requestReviews||=[];if(!game.requestReviews.some(r=>r.id===event.id))game.requestReviews.push({...event,after:currentRequest(),decidedAt:new Date().toISOString()});game.pendingOcean=null;persist();ge('modal-close').hidden=false;closeModal();announce(choice==='kept'?'Ты сохраняешь свой запрос и продолжаешь исследовать его дальше.':'Новый запрос сохранен. Продолжай путь с этой формулировкой.')}
setTimeout(()=>{if(game.pendingOcean&&!game.pendingMovement){ge('journey-cinema').hidden=true;showOcean()}},0);
